/**
 * Tiny blurred copies of each project screenshot (~500 bytes each) used as
 * the CSS background behind the lazily-loaded <img>, so cards paint
 * something meaningful instead of an empty box while the photo loads.
 *
 * Generated by `npm run previews` — do not edit by hand.
 */
export const previewPlaceholders: Record<string, string> = {
  'aaa': 'data:image/jpeg;base64,',
  'clm-electronics': 'data:image/jpeg;base64,',
  'tibay': 'data:image/jpeg;base64,',
  'sureparts': 'data:image/jpeg;base64,',
  'buildwise': 'data:image/jpeg;base64,',
  'cmf-works': 'data:image/jpeg;base64,',
  'ai-tools-hub': 'data:image/jpeg;base64,',
  'aoda': 'data:image/jpeg;base64,',
  'apexbuild': 'data:image/jpeg;base64,',
  'buildfolio': 'data:image/jpeg;base64,',
  'solidbuild': 'data:image/jpeg;base64,',
  'smileright': 'data:image/jpeg;base64,',
  'northstar': 'data:image/jpeg;base64,',
};

export function placeholderFor(slug: string): string | undefined {
  return previewPlaceholders[slug];
}
